const base = pm.variables.get('baseUrl');
function call(method, path, body, headers, baseUrl) {
return new Promise(resolve => {
pm.sendRequest({
url: (baseUrl || base) + path, method: method,
header: Object.assign({ 'Content-Type': 'application/json' }, headers || {}),
body: body === undefined ? undefined : { mode: 'raw', raw: JSON.stringify(body) }
}, (err, res) => {
let json = null;
try { json = res ? res.json() : null; } catch (e) {}
resolve({ failed: !!err, status: res ? res.code : 0, json: json });
});
});
}
const sleep = ms => new Promise(r => setTimeout(r, ms));
async function waitDrain(sku) {
for (let i = 0; i < 200; i++) {
const r = await call('GET', '/api/v1/items/' + sku);
const g = r.json && r.json.data && r.json.data.gate;
if (g && g.pendingWrites === 0) return true;
await sleep(100);
}
return false;
}
async function race(o) {
await call('PUT', '/api/v1/items/' + o.sku, { quantity: o.stock });
const path = '/api/v1/items/' + o.sku + '/reservations' + (o.fast ? '/fast' : '');
const started = Date.now();
const jobs = [];
for (let i = 0; i < o.users; i++) {
const requested = o.qty === 'random' ? 1 + Math.floor(Math.random() * 3) : o.qty;
const headers = o.strategy ? { 'x-reservation-strategy': o.strategy } : {};
const bu = o.bases ? o.bases[i % o.bases.length] : undefined;
jobs.push(call('POST', path, { userId: 'user-' + (i + 1), quantity: requested }, headers, bu)
.then(r => { r.requested = requested; return r; }));
}
const results = await Promise.all(jobs);
const wallMs = Date.now() - started;
const okStatus = o.fast ? 202 : 201;
const accepted = results.filter(r => r.status === okStatus);
const granted = accepted.reduce((t, r) => t + ((r.json && r.json.data && r.json.data.quantity) || 0), 0);
const drained = o.fast ? await waitDrain(o.sku) : true;
return {
users: o.users, stock: o.stock, accepted: accepted.length,
soldOut: results.filter(r => r.status === 409).length,
errors: results.filter(r => r.failed || r.status >= 500 || r.status === 0).length,
granted: granted, partials: accepted.filter(r => r.json.data.quantity < r.requested).length,
demand: results.reduce((t, r) => t + r.requested, 0),
wallMs: wallMs, rps: Math.round(o.users / (wallMs / 1000)), drained: drained
};
}
